From 416420627ef74720cd42461ad2098a2f85bd9bc6 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 10:48:54 +0100
Subject: [PATCH] krunner: place the top bar below floating panels

Floating panels only reserve their thickness, so KRunner at the top of
the screen overlapped a floating top panel. Plasmashell now tells it how
much more space such panels take, and KRunner keeps that much below them.

BUG: 502508
---
 krunner/view.cpp                   | 40 ++++++++++++++++++++++++++-
 krunner/view.h                     |  2 ++
 shell/dbus/org.kde.PlasmaShell.xml | 16 +++++++++++
 shell/panelview.cpp                |  9 ++++++
 shell/panelview.h                  |  2 ++
 shell/shellcorona.cpp              | 44 ++++++++++++++++++++++++++++++
 shell/shellcorona.h                | 12 ++++++++
 7 files changed, 124 insertions(+), 1 deletion(-)

diff --git a/krunner/view.cpp b/krunner/view.cpp
index 1ca6e0d0f1..1ec8c73df0 100644
--- a/krunner/view.cpp
+++ b/krunner/view.cpp
@@ -8,6 +8,8 @@

 #include <QAction>
 #include <QClipboard>
+#include <QDBusPendingCallWatcher>
+#include <QDBusPendingReply>
 #include <QDebug>
 #include <QGuiApplication>
 #include <QPlatformSurfaceEvent>
@@ -90,6 +92,19 @@ View::View(QWindow *)

     connect(qGuiApp, &QGuiApplication::screenRemoved, this, screenRemoved);
     connect(qGuiApp, &QGuiApplication::focusWindowChanged, this, &View::slotFocusWindowChanged);
+
+    // Floating panels only reserve their thickness, ask plasmashell how much more they take
+    QDBusConnection::sessionBus().connect(u"org.kde.plasmashell"_s,
+                                          u"/PlasmaShell"_s,
+                                          u"org.kde.PlasmaShell"_s,
+                                          u"floatingPanelMarginsChanged"_s,
+                                          this,
+                                          SLOT(updateFloatingPanelGaps()));
+    connect(qGuiApp, &QGuiApplication::screenAdded, this, &View::updateFloatingPanelGaps);
+    connect(this, &QWindow::screenChanged, this, [this]() {
+        LayerShellQt::Window::get(this)->setMargins(margins());
+    });
+    updateFloatingPanelGaps();
 }

 View::~View()
@@ -103,7 +118,30 @@ QMargins View::margins()
         const QRect r = screen()->availableGeometry();
         return QMargins({0, r.height() / 3, 0, 0});
     } else {
-        return {}; // Zeros
+        return QMargins({0, m_floatingPanelGaps.value(screen()->name()), 0, 0});
+    }
+}
+
+void View::updateFloatingPanelGaps()
+{
+    const auto screens = QGuiApplication::screens();
+    for (const QScreen *s : screens) {
+        const QString screenName = s->name();
+        auto message = QDBusMessage::createMethodCall(u"org.kde.plasmashell"_s, u"/PlasmaShell"_s, u"org.kde.PlasmaShell"_s, u"floatingPanelMargins"_s);
+        message << screenName;
+        auto watcher = new QDBusPendingCallWatcher(QDBusConnection::sessionBus().asyncCall(message), this);
+        connect(watcher, &QDBusPendingCallWatcher::finished, this, [this, screenName](QDBusPendingCallWatcher *watcher) {
+            watcher->deleteLater();
+            const QDBusPendingReply<QList<int>> reply = *watcher;
+            const int gap = reply.isValid() && reply.value().size() == 4 ? reply.value().at(1) : 0;
+            if (m_floatingPanelGaps.value(screenName) == gap) {
+                return;
+            }
+            m_floatingPanelGaps[screenName] = gap;
+            if (!m_floating && screen()->name() == screenName) {
+                LayerShellQt::Window::get(this)->setMargins(margins());
+            }
+        });
     }
 }

