+QList<int> ShellCorona::floatingPanelMargins(const QString &name) const
+{
+    return m_floatingPanelMargins.value(name, {0, 0, 0, 0});
+}
+
+void ShellCorona::updateFloatingPanelMargins()
+{
+    QHash<QString, QList<int>> floatingPanelMargins;
+    for (PanelView *v : std::as_const(m_panelViews)) {
+        if (!v->isVisible() || !v->screenToFollow() || v->visibilityMode() != PanelView::NormalPanel || !shouldPanelReserveSpace(v)) {
+            continue;
+        }
+        const int gap = v->floatingGap();
+        if (gap <= 0) {
+            continue;
+        }
+        QList<int> &margins = floatingPanelMargins[v->screenToFollow()->name()];
+        margins.resize(4);
+        switch (v->location()) {
+        case Plasma::Types::LeftEdge:
+            margins[0] = gap;
+            break;
+        case Plasma::Types::TopEdge:
+            margins[1] = gap;
+            break;
+        case Plasma::Types::RightEdge:
+            margins[2] = gap;
+            break;
+        case Plasma::Types::BottomEdge:
+            margins[3] = gap;
+            break;
+        default:
+            break;
+        }
+    }
+
+    if (floatingPanelMargins != m_floatingPanelMargins) {
+        m_floatingPanelMargins = floatingPanelMargins;
+        Q_EMIT floatingPanelMarginsChanged();
+    }
+}
